PLANS=[]
def unit(id,start,end,chars,scene,props,map,light,shots):
 PLANS.append(dict(id=id,start=start,end=end,chars=chars.split('；') if chars else [],scene=scene,props=props.split('；') if props else [],map=map,light=light,shots=shots))
def s(d,v,c,a,e,lines=()):return dict(duration=d,view=v,camera=c,action=a,end=e,lines=list(lines))
V='Vera黑色晚宴装';E='Emiliano常服';T='Víctor常服';N='Don Ernesto常服';D='Damián常服';C='Carmen常服';R='Renata常服';Q='Escolta A常服';B='Tiburcio常服';J='Reportero C常服'
H='晚宴酒店大厅'
HALL='会场设于既有晚宴酒店大厅：讲台在北侧矮台，座席面向北；中央通道南北向，主入口在南墙向厅内开，东侧有台阶通矮台。Vera在前排西侧靠中央通道座位，Damián在前排东侧；Reportero C在西侧边道拍摄。Víctor在讲台后，Don Ernesto站台上东侧，Carmen站台上西侧。三名功能性员工在后排西侧，其中一名负责传递文件，不冒充人物表Empleada A。'
LIGHT='沿用大厅吊灯与侧窗日光：窗光由西侧斜照，吊灯提供低弱环境亮度；背景板为无字色块，快门闪光短促，不把全场反复洗白。'
MIC='讲台只有一支无线手持麦克风，起初固定于支架；谁拿到它谁发声扩声，其他现场对白保持真实空间声源，不复制麦克风。'
unit('31-1A',506,516,V,'高层公寓阳台','红色马克笔；白色法律文件',
'阳台北侧为通向公寓的推拉门，南侧栏杆外是城市天际线；Vera站阳台北侧小桌前，左手压文件，右手持红色马克笔。开场只从既有阳台向外取城市楼体局部，手部插镜仍在同一阳台，不把她放到楼外高空。',
'暮色由城市方向映入，红色光面只形成无字的建筑反射；桌面受门内既有灯的间接侧光，文件不出现任何字形。',[
s(3,'城市楼体局部/阳台外望','在栏杆内固定，轻向上摇到楼体红色光面','开场越过栏杆观察改革大道楼体，红色光面由常亮变为一次短闪，再稳定；只呈无字色块。','城市暮色仍在南侧，未显示数字或标题。'),
s(3,'文件与双手俯拍近景','从阳台桌上方垂直观察，沿纸边短移','Vera左手压住白色文件一角，右手将马克笔笔尖落在纸面，沿横向画第一道红线；纸面不显示原印刷文字。','第一道线完成，笔尖离纸，文件未移动。'),
s(3,'右手侧面特写','固定在桌东侧，保留指尖和纸面接触','右手落笔画第二道红线，笔尖在第三处留白上方停住；不凭空出现字母或再次重画第一道。','两道红线留纸面，右手停笔。'),
s(3,'Vera侧后中景/阳台东侧','沿空置门前通道后拉，显出栏杆与桌的关系','Vera看着文件，肩背保持直立，手指将笔握稳；红色楼体反光只留在远处，不投出文字。','Vera留桌前，文件与笔仍由左右手分别控制。')])
unit('31-2A',517,525,V+'；'+E,'高层公寓客厅（日）','白色法律文件；红色马克笔',
'客厅东侧为落地窗，北侧是沙发，餐桌在西侧，阳台在南；Vera已由阳台进屋坐北侧沙发，马克笔与文件放茶几。Emiliano站餐桌东侧，手上没有文件；两人隔茶几与空道交流。沿用已有对应造型，不新增黑皮风衣版本。',
'沿用日景公寓结构，将东窗光写为临近日落的弱侧光，已有落地灯提供暖侧逆光；不把暮色改成正午。',[
s(3,'客厅关系中全景/南侧通道','由阳台门内侧向北短移，落在餐桌与沙发关系','Emiliano站西侧餐桌边，Vera坐北侧沙发；他理平已有西装袖口，向她开口。','两人不因反打换座或换造型。',[521]),
s(3,'Vera侧面中近景','从茶几东侧固定，沙发扶手构成边界','Emiliano句尾跨切传来，Vera看向他，右手整理既有晚宴装肩侧布料后落回扶手；不另披未确认黑风衣。','Vera仍坐沙发，手已放稳。'),
s(4,'Vera近景/茶几南侧','从沙发对角缓推至目光落点','Vera说出原句，声音偏低但清楚，重音落在时间与行动意图；不额外发笑。','Vera说话时自然开合嘴唇。',[524]),
s(3,'Emiliano听者中近景','在餐桌南侧固定，以沙发边缘作远景','Vera原声到完整句尾，Emiliano目光留在她脸上，手指松开袖口。','Emiliano留餐桌旁，无新增回答。'),
s(3,'双人关系中景','沿南侧通道向西后拉，显出两人之间的空道','Vera下颌稍抬后停住，Emiliano保持站姿；纸笔留茶几，为出发前的决定留短停顿。','人物与桌面物件均在原位。')])
# 酒店外景及衔尾蛇文件夹已获用户明确文字设计授权。
unit('31-3B',532,539,T+'；'+N+'；'+J+'；Mujer OS',H,'单反相机；麦克风',HALL+MIC+'此时Vera尚未进场；Mujer为台下未具名年轻女子的现场OS，只作普通群众和声源描述，不新增身份资产。',LIGHT,[
s(3,'会场全景/南端中央通道','从入口向北短推，前排座位框出舞台','Reportero C在西侧边道举相机，记者与宾客已经入座；Vera前排西侧位置暂空。','记者留各自座席或边道，中央通道畅通。'),
s(3,'年轻女子眼部与手部近景','固定在座位斜前方，嘴部留画外','未具名年轻女子坐台下，指尖压住膝上衣料，眼角已有泪痕；其原定OS从同一座位方向传来，嘴部始终不入画。','女子仍坐着，声源没有改为旁白。',[534]),
s(3.5,'前排听众侧后中景','沿西侧边道短移，露出相机与听众的不同深度','女子OS连续说完，附近记者举起手机和相机；画面只见机身背面，不出现文字界面。','所有设备留各自拍摄者手中。'),
s(3,'舞台侧面中全景/东侧台阶','从台阶南端向北伴随，落在台阶上段','Víctor踏上东侧台阶，Don Ernesto随后登阶，二人顺序不变；沿用各自已有造型。','Víctor已上台，Don Ernesto到台阶上段。'),
s(3,'讲台关系中景/台前东南侧','从台阶向西短摇，跟到两人各自停步','Víctor沿台前走到讲台后，Don Ernesto上完台阶停在台上东侧，右手理平原有领口；按已有造型不新增眼镜。','Víctor到讲台，Don Ernesto留台上东侧。'),
s(3,'Víctor侧面近景','在讲台西南侧轻推，保护嘴部和麦克风距离','Víctor双手搭讲台边，靠近支架麦克风，发出原定开场句。','Víctor站位不变，麦克风仍在支架。',[539]),
s(3,'记者与台上关系中景','从西边道向南短拉，以相机形成前景','Víctor原声结束，Reportero C继续对准讲台，听众目光集中；不新增欢呼或音乐。','会场秩序仍完整，入口保持空置。')])
unit('31-3C',540,543,V+'；'+T+'；'+N+'；'+J,H,'单反相机；麦克风',HALL+MIC+'Vera从南门进入，前排西侧靠中央通道的座位空着。Emiliano尚未走入本段镜头。',LIGHT,[
s(3,'鞋与门槛低位近景','从门内西侧侧向伴随，落在完整跨门后的支撑脚','Vera穿已有晚宴装与原鞋履跨过南门槛，裙摆随步伐摆动，门扇已开，不穿过玻璃。','Vera双脚已到厅内。'),
s(4,'Vera侧后全身中景','沿中央通道同向跟随，保持前排目标可见','Vera沿中央通道向北走，记者转头看她；相机在其侧后，未同时要求看到正面细微表情。','她到前排西侧座位旁。'),
s(3,'Vera与空座侧面中景','沿座排前侧空道短弧移动，落在入座动作','Vera由通道移到空椅前，背朝椅背、面向北侧讲台，手扶椅侧，屈膝坐下；裙摆落稳后才交叠双腿。','Vera坐前排西侧，双脚与裙摆位置稳定。'),
s(3,'Vera近景/讲台侧向南','固定，以座椅靠背呈框架','她把双手放到膝上，看向北侧讲台的Víctor；相机位于该视线旁侧，不要求直视镜头。','双手留膝上，目光落在讲台。'),
s(2.5,'前排至舞台关系高角度中全景','由西侧边道较高处轻向东摇，显出台下与台上距离','Vera在前排坐定，Víctor在讲台后；Don Ernesto在台上东侧，中央通道未被占满。','发布会双方位置成立，进入下一集对峙。')])
unit('32-1A',544,560,V+'；'+T+'；'+N+'；'+D+'；'+C+'；'+J+'；'+Q,H,'麦克风；单反相机',HALL+MIC+'Escolta A在南门东侧边道，Carmen在上一场间隔已到台上西侧；Emiliano在南端中央通道外，尚未到前排。',LIGHT,[
s(3,'Vera侧面近景/前排东南侧','缓推，北侧讲台留画外视线目标','Vera坐前排西侧，目光向北，头部仅稍抬；双手仍在膝上，不重做入座。','Vera在原座位。'),
s(3,'Víctor近景/讲台西南侧','固定，支架麦克风与嘴部同框','Víctor点出Vera全名，稍停后眼睑收窄；原资产伤疤保持，不重设计标记。','Víctor仍在讲台后。',[551]),
s(3.5,'Vera过肩望台上中景','在前排西侧固定，Vera肩背为近景、Víctor为中景','Víctor继续抛出指控，Vera肩背不动；背景板不出现文字。','指控句尾完整落下。',[553]),
s(3,'Carmen近景/讲台东南侧','从Víctor侧面短摇到Carmen，落稳后保护口型','Carmen靠近讲台西侧的同一麦克风说话范围，Víctor向东让半步；她看向记者开口，声音不稳但词句完整。','Carmen站台上西侧，麦克风未离支架。',[555]),
s(4,'Carmen侧面近景','沿台前空道向西短移，背景听众形成纵深','Carmen继续控诉，手掌压在讲台侧沿；已有泪痕不再叠加抽泣声或面部扭曲。','Carmen手留台侧，句尾完整。',[557]),
s(3,'Damián手臂与上身中景','固定在前排东侧边道，保留他与座位关系','Damián站到座椅旁，左手把右袖往上推到前臂，右脚向中央通道挪半步后停住；沿用现有常服。','Damián在座侧站定，未冲上舞台。'),
s(3,'记者前景与人群中景','沿西边道向南侧移，显出相机和听众转头','Reportero C按快门，背景三名员工与宾客交换目光；议论保持无词低声，不新增可辨台词。','中央通道仍可通行，Damián留座侧。')])
unit('32-1B',561,568,V+'；'+E+'；'+T+'；'+C+'；'+N+'；'+D,H,'麦克风；公证文件',HALL+MIC+'Emiliano从中央通道南端向前排走，左手持厚文件靠身侧；Vera仍坐前排西侧。',LIGHT,[
s(3.5,'Emiliano侧后中景/中央通道','沿通道向北跟随，保持空位和讲台可见','Emiliano走向前排，在Vera座后放慢脚步，抬眼朝讲台发声；左手文件不换手。','他到Vera身后约半步。',[562]),
s(3,'Emiliano与Vera双人侧面中景','从西侧座排前方向东短弧，落在站者与坐者关系','Emiliano站定，低眼看向Vera后向台上补充回应；Vera仍坐着听完。','Emiliano站座后，Vera准备起身。',[564]),
s(3,'Vera起身全身中景','从座椅侧面固定，完整呈现支撑与站起','Vera双手从膝上移到椅侧，双脚收稳后起身；Emiliano后退半步给她让出通道。','Vera站在前排中央通道边。'),
s(4,'Vera侧后全身中景','沿台前空道向东跟随，东侧台阶保持在画面前方','Vera从前排沿台前空道走到东侧台阶，手扶栏边，踏上前两级；步速正常。','Vera到台阶上段，未瞬移到讲台。'),
s(3,'讲台关系中景/台阶西南侧','轻向北摇，跟到她在讲台南侧站稳','Vera上完台阶，沿台上前沿走到讲台南侧；Víctor与Carmen退到讲台后东、西两侧，Don Ernesto仍在更东侧。','Vera在麦克风南侧可及处，未改变其他人方位。'),
s(4,'Vera近景/台前东南侧','轻推到她与Carmen对视的落点','Vera抬眼看Carmen，发出原问句；麦克风仍在支架，她没有抢夺它。','Vera说完，目光留Carmen。',[567]),
s(2.5,'Carmen听者近景','固定，讲台边线形成斜线','Carmen唇部短暂张开又收住，没有回答；Víctor肩侧留背景，未新增可辨低语。','Carmen停在讲台后西侧。')])
unit('32-1C',569,576,V+'；'+E+'；'+T+'；'+C+'；'+N+'；'+J,H,'公证文件；麦克风；单反相机',HALL+MIC+'Vera站讲台南侧，Víctor在讲台后东侧，Carmen在后西侧。Emiliano已由座后走到台前西侧，左手持成套文件副本；一名功能性员工在其西侧准备接件。',LIGHT,[
s(3,'文件交接侧面近景/台前西侧','固定，双方接触和松手都在画内','Emiliano左手把成套公证文件递向员工，员工双手接住底边并夹稳，Emiliano才松手；他同时说明文件性质。','副本归员工，Emiliano左手空出。',[570]),
s(3,'员工与前排中景','沿前排通行空道向北短移，落在分发过程','员工把文件分成已装订的副本，递给两位前排记者；每次记者握稳后员工才松手。','两份副本分别在两名记者手中，其余留员工。'),
s(4,'记者翻阅手部俯视近景','由西侧边道较高机位向下观察，保留纸背与订口','Emiliano在台前现场继续说明公证内容，声音自然转画外；记者只翻一次页，纸面不出现字迹。','副本保持各自归属，Emiliano仍在台前西侧。',[572]),
s(3.5,'Vera侧面近景/台前东南侧','从文件方向轻摇回Vera，落稳在开口','Emiliano说完后Vera接话，略侧头看文件方向，再把目光转回Carmen；语气清楚，嘴角只轻收。','Vera留讲台南侧，话筒仍在支架。',[574]),
s(3.5,'Carmen与Víctor听者中景','固定在讲台南方，保留两人实际间距','Vera上句连续跨切到句尾，Carmen视线移向纸背，Víctor下颌绷紧；二人不做她的口型。','两名听者仍在台后原位。'),
s(4,'Vera正侧近景','沿台前向东短弧，落在她看向听众的眼神','Vera继续补完第二句判断，按省略号自然停顿；不把一句拆成两次重新起音。','Vera说完，右手仍空着。',[576]),
s(2,'讲台与台前关系中景','短拉显示Víctor与麦克风之间的半步距离','Vera看向台下，Víctor从东后方准备上前，Carmen让开侧边；文件仍在记者和员工手中。','Víctor尚未取走话筒，下一动作有明确起点。')])
unit('32-1D',577,588,V+'；'+T+'；'+N+'；'+C+'；'+E+'；'+Q+'；'+B+'；'+J,H,'麦克风；单反相机',HALL+MIC+'Vera在讲台南侧，Víctor在东后半步，Carmen在后西侧。Tiburcio在南门外，Escolta A与一名普通安保各扶其一侧上臂；不复制Escolta A身份。Emiliano在台前西侧。',LIGHT,[
s(3,'麦克风与两人中近景/台前东南侧','固定，手掌与支架接触清楚','Víctor跨前半步，右手从支架抽走麦克风；Vera把右侧肩线向西让出，手不与他争夺。','话筒在Víctor右手，支架留空。'),
s(3,'Víctor近景','缓推至其开口，话筒不遮嘴','Víctor靠近右手话筒，发出质问，音量提高但字词不破音；Vera在他西侧半步。','Víctor右手未换位。',[578]),
s(4,'Víctor侧面中景','由讲台西南侧向南摇少许，保留指向入口的左手','Víctor左手指向南门，给出关于十年前的指控；右手始终持话筒。','左手指向入口，右手话筒在嘴前。',[580]),
s(2.5,'Vera听者近景/台前东侧','固定，入口留在她视线转向的画外方向','Víctor下令带证人，Vera只把视线转向南门；下令词保留同一现场声源。','Vera看向南门，未离开舞台。',[582]),
s(4,'南门至通道中全景/西边道','先对南门固定，开门后沿通道同向短移','普通安保先用空出的外侧手推门，再重新扶住Tiburcio上臂；Escolta A扶另一侧，两人带他跨门槛进入中央通道。','三人都已在厅内，门扇不穿过身体。'),
s(4,'证人侧后全身中景','沿中央通道向北跟随，舞台保持前方目标','Tiburcio被带到台前中央，双脚仍自行落地；两名看管者在其两侧随行，帽檐遮住上半脸。','三人到台前中央停下，Escolta A在证人东侧。'),
s(3,'Tiburcio近景/台前西侧','从手臂接触轻摇至帽檐下的眼神','Tiburcio抬头少许，嘴唇压合，目光不与Vera对上；不新加吞咽声。','他站台下中央，两臂仍被扶住。'),
s(2.5,'会场关系高角度中全景','从西边道较高位置向东短摇，显出舞台与证人','记者同时举机，短促快门与闪光集中到证人；背景板仍无可读文字。','台上台下位置成立，证人未上台。')])
unit('33-1A',589,598,B+'；'+Q+'；'+V+'；'+T+'；'+N+'；'+D+'；'+C+'；'+E+'；'+J,H,'麦克风；单反相机',HALL+MIC+'Tiburcio站台下中央，两名看管者在两侧，Escolta A在东侧。Víctor站讲台后东侧，右手持话筒；Vera站讲台南侧偏西，Carmen在后西侧；Damián在前排东侧座旁。',LIGHT,[
s(3,'证人与舞台关系中全景/西边道','侧移绕过已存在的相机前景，落在证人被看管的关系','Tiburcio帽檐低垂，两名看管者仍扶上臂；舞台人物看向他，记者留通道两侧。','证人仍在台下中央，不站到讲台后。'),
s(4,'Tiburcio侧面近景','从台前西侧轻推，落在他抬头后的嘴部','Tiburcio抬头发出原定证词，声音低而沙哑；眼神短暂看向Vera后移开。','证词尚在连续发声，两名看管者未松手。',[596]),
s(4,'Damián听者中近景/前排东侧','固定，以证人肩部作远处关系参照','证词跨切持续，Damián把双手插进西装裤袋，目光转向台上的Víctor，头部随后跟上。','Damián留座旁，没有走向证人。'),
s(3,'Víctor侧面近景','从台前西南侧固定，话筒在他右手下方','证词完整结束，Víctor看向Damián，单侧嘴角轻抬后停住；不新增笑声。','话筒仍在Víctor右手。'),
s(3,'舞台三人关系中景','沿台前向东短移，显出空支架与Vera的可及距离','Víctor把话筒放回讲台支架并松手，Vera向讲台靠半步；Carmen留后西侧，Don Ernesto留东侧。','麦克风回到支架，Vera有明确可发声位置。')])
unit('33-1B',599,608,V+'；'+B+'；'+T+'；'+Q+'；'+C+'；'+N+'；'+E,H,'麦克风',HALL+MIC+'话筒已回讲台支架，Vera在南侧偏西，Víctor在讲台后东侧；Tiburcio站台下中央，Escolta A与普通安保各扶一侧上臂。',LIGHT,[
s(3,'Vera近景/台前东南侧','轻推，停在她与台下证人的视线关系','Vera靠近支架麦克风，直接问证人是否在场；下颌放松，问句清楚短促。','Vera未触碰话筒。',[600]),
s(2,'Tiburcio近景/台前西侧','固定，Vera在画外较高视线方向','Tiburcio避开Vera视线，低头快速肯定；声源在台下，声音不从舞台话筒发出。','Tiburcio仍被两侧看管。',[602]),
s(4,'Vera俯视证人过肩中景','从Vera西后肩旁向南下方观察，帽檐和看管者构成中景','Vera问风向，身体留在台上；证人抬眼试图判断她的意思。','问题完整结束，双方距离未改变。',[603]),
s(3,'Tiburcio侧面近景','固定，帽檐阴影有可读眼神','Tiburcio稍停才答，目光飘向台上的Víctor；只保留一次短促迟疑，不加吞咽音。','回答完整，Tiburcio未挪脚。',[605]),
s(4,'Vera侧面中近景','从台前西南侧向东短弧，落在她转向记者的姿态','Vera直起身体，指出救援报告与原定风向词；表情以唇角轻收表达，不新增解释性台词。','Vera仍在讲台南侧，右手空着。',[607]),
s(3,'Tiburcio与Víctor纵深中景','由证人西侧轻向后拉，揭出他目光的台上落点','Vera句尾跨切说完，Tiburcio看向Víctor，嘴唇不再抿紧；Víctor留在台后东侧。','台下求助目光与台上接收方明确。')])
unit('33-1C',609,614,V+'；'+B+'；'+T+'；'+Q+'；'+J+'；'+C+'；'+N,H,'麦克风；单反相机',HALL+MIC+'Vera在台上讲台南侧，Tiburcio在台下中央，两名看管者仍在其两侧；Víctor在讲台后东侧，麦克风固定支架。',LIGHT,[
s(3.5,'Vera近景/台前东南侧','短推后稳住，留出她问完后的停顿','Vera把目光重新落到Tiburcio，问火焰颜色；不额外前冲缩短台阶距离。','Vera站位不变。',[610]),
s(2,'Tiburcio近景','固定，在他开口时保护嘴部可读','Tiburcio立即答出原色词，句尾落下后目光停住，不新增第二个词。','证人仍在台下中央。',[611]),
s(4,'Vera侧面中近景','沿台前从西向东短移，停在她朝记者说话的位置','Vera指出化学品仓库火焰特征，原文大写只作自然语义重音，未安排尖叫。','她的原声保持连续，讲台支架不移动。',[613]),
s(4,'Reportero C与证人关系中景','从西边道向北侧移，以镜头机身产生前景视差','Vera原声跨切说完整句，Reportero C举相机对准Tiburcio；背景记者随后举机，听众低声议论无可辨新词。','拍摄目标转为证人，通道仍不被围堵。'),
s(3,'Víctor听者近景','从台前西南侧固定，Vera虚化侧影在画边','Víctor听完后鼻翼略张又收住，下颌紧张保留；没有剧烈喘气、变色或新增咒骂。','Víctor还在讲台后东侧，准备转向后排声源。')])
unit('33-1D',615,624,R+'；'+V+'；'+T+'；'+D+'；'+C+'；'+N+'；'+E+'；'+B+'；'+Q+'；'+J,H,'麦克风；单反相机',HALL+MIC+'Renata一直坐后排东侧靠边道位置，本段起身发声；Vera在台上讲台南侧，Víctor在后东侧，话筒固定支架。Tiburcio在台下中央，Escolta A与普通安保仍在两侧，Damián在前排东侧座旁。',LIGHT,[
s(3,'Renata侧后全身中景/东边道','由后排空座间向上轻抬，跟到她站稳','Renata双脚收稳后从后排起身，手掌离开椅背，面向北侧舞台；脸上已有伤痕沿用先前状态，不新增伤口。','Renata站后排座侧，不走入中央通道。'),
s(4,'Renata近景/后排西南侧','缓推后稳住，让面部与指向有清楚边界','Renata说出第一句控诉，声音带不稳但词语完整；右手由身侧抬起指向舞台，幅度不盖住脸。','右手指向北侧，Renata仍站座旁。',[616]),
s(3,'Vera听者近景/台前东南侧','先随她视线向南转，再在侧面落稳','Renata原声跨切说完，Vera视线先转向后排，头部跟随；她不代说后排台词。','Vera留舞台，目光到后排东侧。'),
s(4,'Renata侧面中近景','从东边道固定，后排座椅形成纵深','Renata继续作证，句中的代词重音按原文保留；右手保持指向后放低，不反复挥动。','第二句控诉连续发声，双脚不移。',[618]),
s(3,'Víctor与麦克风中近景','从台前西侧短移，跟到他靠近话筒','Renata说完后Víctor从讲台后东侧跨近半步，右掌拍讲台一次，对麦克风发出原定制止词；不取下话筒。','右掌落在台面，话筒仍在支架。',[620]),
s(4,'Renata近景/后排西南侧','固定，给她回击的声音完整起点','Renata迎视台上，追问被关阁楼的事实；声音清楚坚决，只在句中自然换气，不叠加尖叫。','她仍站后排，原声跨切继续。',[622]),
s(4,'台上台下关系高角度中全景','由西侧边道较高处向北慢摇，以后排Renata至台上Víctor为对角线','Renata整句连续说完，宾客视线在后排与台上之间转移；Vera仍在讲台南侧，证人与看管者留台前。','声源与所有人位置保持，不新增可辨人群台词。'),
s(3,'Víctor近景/台前西南侧','固定，停在他未能接话的状态','Víctor看向后排，原来准备张口的唇缝合住，右掌仍压在讲台；不重复拍台或再喊一次。','Víctor留讲台后，Renata站后排，冲突落在沉默。')])
EXTERIOR='酒店正门沿东西向立面，门内大厅在北、门外车道在南；门前有三层宽台阶，东侧留缓坡。黑色轿车沿东西向停在台阶南侧，右后车门朝北面向台阶；门外西侧留相机通道。外景按已获授权的文字设计，保持日夜为同一建筑，不冒用其他场景标签。'
unit('31-3A',526,531,'Oficial A常服','酒店正门（外·日）','两辆警车；黑色轿车',EXTERIOR+'Oficial A站门口东侧，另一名普通警员站西侧，功能性警员不另绑定人物身份。',
'午后日光从西南侧斜照立面，入口檐口提供自然阴影；警灯只在车身和地面形成短促红蓝反射，招牌无字。',[
s(3,'酒店外景全景/车道西侧','沿人行空道向东平移，落在正门与两辆警车关系','黑色豪车停在门前车道，两辆警车分停入口东西两侧；门口警员在台阶两端维持通道，车辆不封住台阶。','酒店入口与通行路线清楚，车门均关闭。'),
s(3,'警员与入口中景/台阶西南侧','从车身前景向北短移，显出门前的警员','Oficial A留东侧，普通警员在西侧抬手示意来客沿中央入口通行；只作无词手势，不新增口令。','中央入口保持畅通，警员没有离岗。'),
s(3,'酒店门面中全景','从台阶下方轻向上摇到入口檐口后停住','入口玻璃反射车道与日光，原招牌位置仅留建筑色面；原稿酒店名和会务标题不显示。','以门框结构切入同一酒店大厅。')])
unit('33-2A',625,635,V+'；'+Q,'酒店正门（外·夜）；轿车内','金色衔尾蛇纹章黑色文件夹',EXTERIOR+
'从日间会场到夜间门外明确省略离场过程。Vera站台阶上第二层、面向南侧车道，双臂起初交叠；Escolta A坐轿车右后座，文件夹平放在其左侧空座，封面金色蛇咬尾图形朝上，不含可读字形。人物沿用已有造型，不另创黑风衣或全黑西装版本。',
'酒店檐口既有暖灯从侧上方照台阶，车内顶灯只在车门开启后亮起；玻璃幕墙反射真实车道灯，不显示招牌文字。',[
s(3,'酒店与车辆关系全景/车道西侧','沿人行空道向东短移，随轿车停稳后落稳','黑色轿车缓慢驶到台阶南侧停住，Vera在第二层台阶双臂交叠，面向车；她不同时出现在车内。','轿车停稳，右后门仍关闭。'),
s(4,'右后车门侧面中景/车道东北侧','固定，完整呈现开门与落脚','Escolta A从车内推开右后门，先落右脚再转身站到车门外；空出的门扇停在开启位置，车内文件夹还在左侧空座。','Escolta A站车外，门已开，文件夹未移动。'),
s(3,'车内文件夹与手部近景/开启车门外','在门外俯视后座，轻推到两手接触点','Escolta A俯身从开启门口伸入双手，分别托文件夹两侧下缘，抬离座垫并收回身前；相机不穿过车壳。','文件夹由双手托住，封面朝上，车门仍开启。'),
s(3,'台阶侧面双人中景','沿台阶西侧空道侧向伴随，停在交接距离','Escolta A持文件夹走到第一层台阶，Vera在第二层放开交叠双臂，双手伸向文件夹两侧；两人相距一臂。','双方手指均已接触文件夹，Escolta A仍托底。'),
s(3,'文件夹交接手部近景','固定，两侧手指与托底手掌在同一焦平面','Vera双手夹稳文件夹两侧并托住下缘后，Escolta A才松手退回半步；不在切镜时转移归属。','文件夹归Vera，Escolta A双手空出。'),
s(3,'文件夹封面特写','沿封面边缘短移，落在金色圆环蛇纹章','Vera左手托底、右手扶侧边，将封面略向自己倾斜；金色蛇咬尾图形随灯光改变反射，小字区域为无字黑面。','纹章为图形，无任何可读字母，文件夹仍在双手。'),
s(3,'双人关系中景/台阶西侧','由文件夹轻向上摇至Vera与Escolta A的目光关系','Vera抬眼看Escolta A一瞬，再把文件夹靠近身前；Escolta A留下一层台阶，车门仍开，两人都不发声。','Vera持文件夹站第二层台阶，Escolta A站第一层，结尾归属与位置明确。')])
